WITH q AS (SELECT a.appointment_id,a.appointment_date,a.status,a.reason,p.patient_id,p.first_name AS patient_first,p.last_name AS patient_last,p.contact_number,d.doctor_id,d.first_name AS doctor_first,d.last_name AS doctor_last,sp.specialty_name FROM public.appointments a JOIN public.patients p ON p.patient_id=a.patient_id JOIN public.doctors d ON d.doctor_id=a.doctor_id LEFT JOIN public.specialties sp ON sp.specialty_id=d.specialty_id ORDER BY a.appointment_date) SELECT jsonb_build_object('rows',count(*),'md5',md5(COALESCE(string_agg(to_jsonb(q)::text,E'\n' ORDER BY to_jsonb(q)::text),''))) FROM q;
